f['io/tvos/TmdbClient.java']='''package io.tvos;import org.json.*;class TmdbClient {static boolean key=true,failLogo;static JSONObject search,images;static int requests;static String lastSearch;static boolean hasKey(){return key;}static JSONObject get(String path,java.util.function.Consumer<java.net.HttpURLConnection> opened)throws java.io.IOException,org.json.JSONException {requests++;if(path.startsWith("/search/")){lastSearch=path;return search;}if(failLogo)throw new java.io.IOException();return images;}}'''
