f['io/tvos/DockArtworkHarness.java']='''package io.tvos;import org.json.*;import android.graphics.*;import android.os.SystemClock;
public class DockArtworkHarness {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}static JSONObject movie(int id,String poster,String year){return new JSONObject().put("id",id).put("media_type","movie").put("title","Film").put("release_date",year+"-01-01").put("poster_path",poster).put("backdrop_path","/wide.jpg");}
 public static void main(String[] args)throws Exception {AppLanguage.select("ru");
 JSONObject old=movie(1,"/a.jpg","2020"),fresh=movie(2,"/b.jpg","2026");JSONArray items=new JSONArray().put(old).put(fresh);
 check(DockArtwork.match(items,"Film","https://mirror/b.jpg?token=x","")==fresh,"poster filename identifies exact title across mirrors");check(DockArtwork.match(items,"Film","","2026")==fresh,"release year disambiguates remakes");check(DockArtwork.match(items,"Film","","")==null,"ambiguous title never chooses arbitrary film");check(DockArtwork.match(items,"Other","","")==null,"unrelated result rejected");
 JSONObject dog=movie(77,"/dog.jpg","2026").put("title","Собачьи звёзды").put("original_title","The Dog Stars");JSONArray dogItems=new JSONArray().put(dog);check(DockArtwork.match(dogItems,"Собачьи звезды","","2026")==dog,"Russian e and yo do not prevent exact matching");check(DockArtwork.match(dogItems,"Собачьи звезды / The Dog Stars","","2026")==dog,"bilingual labels match either exact title");check(DockArtwork.match(dogItems,"Собачьи звезды / The Dog Stars","","2025")==null,"bilingual matching still enforces year");JSONObject otherDog=movie(78,"/other.jpg","2026").put("title","The Dog Stars");check(DockArtwork.match(new JSONArray().put(dog).put(otherDog),"Собачьи звезды / The Dog Stars","","2026")==null,"bilingual aliases do not bypass ambiguity rejection");TmdbClient.search=new JSONObject().put("results",dogItems);DockArtwork dogMatch=DockArtwork.lookup("Собачьи звезды / The Dog Stars","","2026",connection->{});check(!dogMatch.backdrop.isEmpty()&&TmdbClient.lastSearch.contains("query=The+Dog+Stars&"),"bilingual search uses original title rather than combined label");
 JSONArray logos=new JSONArray().put(new JSONObject().put("file_path","/en.png").put("iso_639_1","en")).put(new JSONObject().put("file_path","/ru.png").put("iso_639_1","ru")).put(new JSONObject().put("file_path","/bad.svg").put("iso_639_1","ru"));check(DockArtwork.logo(logos,"ru").equals("/ru.png"),"localized PNG logo preferred");check(DockArtwork.logo(logos,"de").equals("/en.png"),"English logo fallback");check(DockArtwork.image("//../bad","w500").isEmpty(),"invalid image path rejected");
 TmdbClient.search=new JSONObject().put("results",items);TmdbClient.images=new JSONObject().put("logos",logos);DockArtwork found=DockArtwork.find("Film","https://mirror/b.jpg","2026");check(found.backdrop.endsWith("/w1280/wide.jpg")&&found.logo.endsWith("/w500/ru.png"),"portrait-only publisher gets matched landscape and logo");int requests=TmdbClient.requests;check(DockArtwork.find("Film","https://mirror/b.jpg","2026")==found&&TmdbClient.requests==requests,"revisiting artwork reuses metadata without duplicate search/logo requests");DockArtwork early=DockArtwork.lookup("Film","","2026",connection->{});check(!early.backdrop.isEmpty()&&early.logo.isEmpty()&&TmdbClient.requests==requests+1,"landscape identity returns before logo endpoint is requested");TmdbClient.failLogo=true;found=DockArtwork.find("Film","","2026");check(!found.backdrop.isEmpty()&&found.logo.isEmpty(),"logo endpoint failure preserves Seena backdrop");TmdbClient.failLogo=false;for(int i=0;i<20;i++)DockArtwork.find("Film","https://cache/"+i+"/b.jpg","2026");java.lang.reflect.Field cache=DockArtwork.class.getDeclaredField("CACHE");cache.setAccessible(true);check(((java.util.Map<?,?>)cache.get(null)).size()==16,"metadata cache bounded to sixteen string-only records");TmdbClient.key=false;check(DockArtwork.find("Film","","").backdrop.isEmpty(),"no key leaves published artwork usable");
 DockBanner b=new DockBanner();Backdrop backdrop=new Backdrop(1);SystemClock.now=1000;b.show(new DockBackdrop.Artwork(backdrop,"Film",null),false);Canvas c=new Canvas();b.draw(c,1,false);check(c.entries.size()==1&&c.entries.get(0).kind.equals("text")&&c.entries.get(0).color==0xFFFFFFFF,"title fallback uses white text only, no vignette/panel");check(c.entries.get(0).l==40,"title left aligned at common screen inset");Bitmap logo=new Bitmap(7);logo.width=1000;logo.height=200;
 SystemClock.now=2000;b.show(new DockBackdrop.Artwork(backdrop,"Film",logo),true);SystemClock.now=2130;b.tick(2130);c=new Canvas();b.draw(c,1,false);check(c.entries.size()==1&&c.entries.get(0).kind.equals("text")&&Math.abs(c.entries.get(0).alpha-128)<=1,"outgoing title fades before logo is drawn");SystemClock.now=2260;b.tick(2260);c=new Canvas();b.draw(c,1,false);check(c.entries.isEmpty(),"title gone before logo entrance");SystemClock.now=2470;b.tick(2470);c=new Canvas();b.draw(c,1,false);check(c.entries.size()==1&&c.entries.get(0).kind.equals("bitmap")&&c.entries.get(0).l==40&&c.entries.get(0).r-c.entries.get(0).l<=420&&Math.abs(c.entries.get(0).alpha-128)<=1,"logo fades in exclusively and fits left-side bounds");b.tick(2680);check(!b.tick(2681),"caption stops requesting frames after fade");b.show(null,false);c=new Canvas();b.draw(c,1,false);check(c.entries.isEmpty(),"clearing artwork clears caption");
 DockBanner waiting=new DockBanner();SystemClock.now=3000;waiting.show(new DockBackdrop.Artwork(backdrop,"",null),true);check(!waiting.tick(3000)&&waiting.nextDelay(3000)==Long.MAX_VALUE,"pending metadata exposes no provisional title");SystemClock.now=3100;waiting.show(new DockBackdrop.Artwork(backdrop,"Film",null),true);check(!waiting.tick(3100)&&waiting.nextDelay(3100)==700,"fallback waits without continuous animation frames");SystemClock.now=3400;waiting.show(new DockBackdrop.Artwork(backdrop,"Film",null),true);check(waiting.nextDelay(3400)==400,"repeat result does not postpone title forever");SystemClock.now=3500;waiting.show(new DockBackdrop.Artwork(backdrop,"Film",logo),true);SystemClock.now=3710;waiting.tick(3710);c=new Canvas();waiting.draw(c,1,false);check(c.entries.size()==1&&c.entries.get(0).kind.equals("bitmap"),"arriving logo cancels delayed title, no title underneath");SystemClock.now=5000;waiting.tick(5000);waiting.show(null,true);SystemClock.now=5130;waiting.tick(5130);c=new Canvas();waiting.draw(c,1,false);check(c.entries.size()==1&&c.entries.get(0).alpha<255,"caption fades when background is cleared");SystemClock.now=5260;waiting.tick(5260);c=new Canvas();waiting.draw(c,1,false);check(c.entries.isEmpty()&&!waiting.tick(5261),"cleared caption releases outgoing artwork and sleeps");
 DockBanner fallback=new DockBanner();SystemClock.now=6000;fallback.show(new DockBackdrop.Artwork(backdrop,"Film",null),true);SystemClock.now=6500;fallback.tick(6500);c=new Canvas();fallback.draw(c,1,false);check(c.entries.isEmpty(),"title hidden for entire fallback delay");SystemClock.now=6910;fallback.tick(6910);c=new Canvas();fallback.draw(c,2,false);check(c.entries.size()==1&&c.entries.get(0).l==80&&Math.abs(c.entries.get(0).alpha-128)<=1,"delayed title fades in and scales inset for 4K");fallback.show(null,false);fallback.show(new DockBackdrop.Artwork(backdrop,"Film",logo),false);c=new Canvas();fallback.draw(c,1,false);check(c.entries.size()==1&&c.entries.get(0).alpha==255&&!fallback.tick(6910),"Reduced Motion uses immediate exclusive caption without frame loop");
 c=new Canvas();fallback.draw(c,1,true);check(c.entries.size()==1&&c.entries.get(0).l==70&&c.entries.get(0).t==70,"logo uses seventy-pixel top and left inset when both header widgets are disabled");c=new Canvas();fallback.draw(c,2,true);check(c.entries.get(0).l==140&&c.entries.get(0).t==140,"compact header inset scales for 4K");fallback.show(new DockBackdrop.Artwork(backdrop,"Film",null),false);c=new Canvas();fallback.draw(c,1,true);check(c.entries.get(0).l==70&&c.entries.get(0).t-36*.75f==70,"title fallback follows same empty-header anchor");
 System.out.println("PASS: exact artwork matching, ambiguous-title rejection, portrait fallback, logo language/failure, title and logo geometry");}
}'''
